// ===== CONFIGURAÇÃO (fácil de ajustar ao vivo) =====
const DESCONTO_MINIMO = 50;   // % mínimo de desconto
const METACRITIC_MIN = 70;    // nota mínima da crítica...
const STEAM_MIN = 80;         // ...ou % mínimo de avaliações positivas na Steam
const MAX_ITENS = 5;

const LOJAS = { '1': 'Steam', '7': 'GOG' };

// Faixa de oferta conforme o desconto (a primeira que combinar vence)
const FAIXAS = [
  { min: 90, nome: 'Imperdível', cor: 15548997 },
  { min: 75, nome: 'Ótima oferta', cor: 16705372 },
  { min: 0,  nome: 'Boa oferta', cor: 5763719 },
];

const resultado = [];

for (const item of $input.all()) {
  const n = item.json;

  // Validação: descarta itens sem os campos essenciais
  const preco = parseFloat(n.salePrice);
  const original = parseFloat(n.normalPrice);
  if (!n.dealID || !n.title || isNaN(preco) || isNaN(original)) continue;

  // Filtro por desconto
  const desconto = Math.round(parseFloat(n.savings));
  if (isNaN(desconto) || desconto < DESCONTO_MINIMO) continue;

  // Filtro por qualidade (nota da crítica OU avaliação dos jogadores)
  const metacritic = parseInt(n.metacriticScore) || 0;
  const steam = parseInt(n.steamRatingPercent) || 0;
  if (metacritic < METACRITIC_MIN && steam < STEAM_MIN) continue;

  const faixa = FAIXAS.find(f => desconto >= f.min) || FAIXAS[FAIXAS.length - 1];

  resultado.push({
    json: {
      title: n.title,
      link: 'https://www.cheapshark.com/redirect?dealID=' + encodeURIComponent(n.dealID),
      loja: LOJAS[n.storeID] || 'Outra loja',
      preco: preco.toFixed(2),
      precoOriginal: original.toFixed(2),
      desconto,
      faixa: faixa.nome,
      cor: faixa.cor,
      thumb: n.thumb || '',
      // Chave de deduplicação: se o preço mudar, vira uma notícia nova
      chave: n.gameID + '-' + n.storeID + '-' + n.salePrice,
    },
  });
}

// Maiores descontos primeiro, limitado à quantidade configurada
resultado.sort((a, b) => b.json.desconto - a.json.desconto);

return resultado.slice(0, MAX_ITENS);

