const IDADE_MAX_DIAS = 7;   // ignora posts mais antigos que isso
const MAX_ITENS = 3;
const COR_PSN = 28881;      

// Só passam posts cujo TÍTULO cite alguma destas palavras
const PALAVRAS_PROMO = [
  'deals', 'deal', 'sale', 'discount', 'discounts',
  'savings', 'promotion', 'black friday',
];

// \b evita falsos positivos (ex.: "sale" dentro de "wholesale")
const contem = (texto, termos) =>
  termos.some(t => new RegExp(`\\b${t}\\b`, 'i').test(texto));

const limite = IDADE_MAX_DIAS * 24 * 60 * 60 * 1000;
const resultado = [];

for (const item of $input.all()) {
  const n = item.json;

  // Validação: descarta itens sem título, link ou data válida
  if (!n.title || !n.link || isNaN(Date.parse(n.isoDate))) continue;

  // Filtro de data: só posts recentes
  if (Date.now() - Date.parse(n.isoDate) > limite) continue;

  // Filtro por palavras de promoção no título
  if (!contem(n.title, PALAVRAS_PROMO)) continue;

  resultado.push({
    json: {
      title: n.title,
      link: n.link,
      resumo: (n.contentSnippet || '').slice(0, 300),
      isoDate: n.isoDate,
      cor: COR_PSN,
    },
  });
}

// Mais recentes primeiro, limitado à quantidade configurada
resultado.sort((a, b) => Date.parse(b.json.isoDate) - Date.parse(a.json.isoDate));

return resultado.slice(0, MAX_ITENS);

